html.life-email-bill-mode #m-bill {\\n        position:fixed !important;\\n        inset:0 !important;\\n        z-index:9000 !important;\\n\\n        display:flex !important;\\n        align-items:stretch !important;\\n\\n        padding:0 !important;\\n        background:#f2faf6 !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill .modal {\\n        display:flex !important;\\n        flex-direction:column !important;\\n\\n        width:100vw !important;\\n        max-width:100vw !important;\\n        height:100dvh !important;\\n        max-height:100dvh !important;\\n\\n        margin:0 !important;\\n        overflow:hidden !important;\\n\\n        border:0 !important;\\n        border-radius:0 !important;\\n        box-shadow:none !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill .m-head {\\n        position:relative !important;\\n        flex:0 0 auto !important;\\n        z-index:50 !important;\\n\\n        min-height:68px !important;\\n        padding:17px 65px 15px 18px !important;\\n\\n        color:#ffffff !important;\\n        background:linear-gradient(\\n            135deg,\\n            #053b2a,\\n            #0b6b4a,\\n            #0f8a5f\\n        ) !important;\\n\\n        border:0 !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill #bill-title {\\n        color:#ffffff !important;\\n        font-size:20px !important;\\n        font-weight:900 !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill .m-x {\\n        position:absolute !important;\\n        top:13px !important;\\n        right:14px !important;\\n\\n        width:42px !important;\\n        height:42px !important;\\n\\n        color:#ffffff !important;\\n        background:rgba(255,255,255,.16) !important;\\n        border:1px solid rgba(255,255,255,.28) !important;\\n        border-radius:50% !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill .m-body {\\n        flex:1 1 auto !important;\\n\\n        padding:14px 12px 145px !important;\\n        overflow-x:hidden !important;\\n        overflow-y:auto !important;\\n\\n        background:#f2faf6 !important;\\n        -webkit-overflow-scrolling:touch;\\n    }\\n\\n    html.life-email-bill-mode #m-bill .card,\\n    html.life-email-bill-mode #m-bill .b-sec {\\n        overflow:hidden !important;\\n        border:1px solid #d2eadc !important;\\n        border-radius:13px !important;\\n        box-shadow:0 5px 18px rgba(5,59,42,.08) !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill .tbl {\\n        display:block !important;\\n        width:100% !important;\\n        overflow-x:auto !important;\\n        background:#ffffff !important;\\n    }\\n\\n    /*\\n     * Hide native Approve/Reject buttons.\\n     * Only the fixed bottom buttons will remain.\\n     */\\n    html.life-email-bill-mode\\n    #m-bill button[onclick*=\\"billApprove\\"],\\n\\n    html.life-email-bill-mode\\n    #m-bill button[onclick*=\\"billReject\\"] {\\n        display:none !important;\\n    }\\n\\n    /*\\n     * Hide the Billing page behind the modal.\\n     */\\n    html.life-email-bill-mode #v-approvals,\\n    html.life-email-bill-mode #v-billing {\\n        visibility:hidden !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill {\\n        visibility:visible !important;\\n    }\\n\\n    html.life-email-bill-mode #m-bill * {\\n        visibility:visible !important;\\n    }\\n}\\n\\n\\n/* Desktop fallback */\\n@media (min-width:701px) {\\n\\n    #life-email-bill-actions {\\n        right:24px;\\n        bottom:20px;\\n        left:auto;\\n        width:450px;\\n        border:1px solid #d2eadc;\\n        border-radius:16px;\\n        box-shadow:0 16px 45px rgba(5,59,42,.25);\\n    }\\n}\\n\\n</style>\\n\\n<script id=\\"life-direct-email-bill-v5-script\\">\\n\\n(function () {\\n\\n    var directStarted = false;\\n    var directRequest = null;\\n    var directInvoice = null;\\n    var directInvoiceDoc = null;\\n\\n\\n    function getEmailParameters() {\\n\\n        var searches = [];\\n\\n        searches.push(\\n            window.location.search || \\"\\"\\n        );\\n\\n        try {\\n            if (\\n                window.parent &&\\n                window.parent !== window\\n            ) {\\n                searches.push(\\n                    window.parent.location.search || \\"\\"\\n                );\\n            }\\n        } catch (error) {}\\n\\n        var completeSearch =\\n            searches.join(\\"&\\");\\n\\n        var parameters =\\n            new URLSearchParams(\\n                completeSearch.replace(/^\\\\\\\\?/, \\"\\")\\n            );\\n\\n        return {\\n            invoice:\\n                parameters.get(\\"invoice\\") || \\"\\",\\n\\n            request:\\n                parameters.get(\\"request\\") || \\"\\"\\n        };\\n    }\\n\\n\\n    function removeElement(id) {\\n\\n        var element =\\n            document.getElementById(id);\\n\\n        if (\\n            element &&\\n            element.parentNode\\n        ) {\\n            element.parentNode.removeChild(\\n                element\\n            );\\n        }\\n    }\\n\\n\\n    function showLoader() {\\n\\n        if (\\n            document.getElementById(\\n                \\"life-email-bill-loader\\"\\n            )\\n        ) {\\n            return;\\n        }\\n\\n        var loader =\\n            document.createElement(\\"div\\");\\n\\n        loader.id =\\n            \\"life-email-bill-loader\\";\\n\\n        loader.innerHTML =\\n            \'<div class=\\"life-email-loader-card\\">\' +\\n                \'<div class=\\"life-email-spinner\\"></div>\' +\\n                \\"<div>Opening approval bill…</div>\\" +\\n                \'<div style=\\"margin-top:5px;\' +\\n                \'color:#789889;font-size:12px\\">\' +\\n                    \\"Please wait\\" +\\n                \\"</div>\\" +\\n            \\"</div>\\";\\n\\n        document.body.appendChild(loader);\\n    }\\n\\n\\n    function showError(message) {\\n\\n        removeElement(\\n            \\"life-email-bill-actions\\"\\n        );\\n\\n        var loader =\\n            document.getElementById(\\n                \\"life-email-bill-loader\\"\\n            );\\n\\n        if (!loader) {\\n            showLoader();\\n\\n            loader =\\n                document.getElementById(\\n                    \\"life-email-bill-loader\\"\\n                );\\n        }\\n\\n        loader.innerHTML =\\n            \'<div class=\\"life-email-result-card\\">\' +\\n                \'<div class=\\"life-email-result-icon\\">\' +\\n                    \\"⚠️\\" +\\n                \\"</div>\\" +\\n                \'<div class=\\"life-email-result-message\\">\' +\\n                    esc(message) +\\n                \\"</div>\\" +\\n            \\"</div>\\";\\n    }\\n\\n\\n    function isAuthorized(request) {\\n\\n        if (!request) {\\n            return false;\\n        }\\n\\n        var selectedUser = String(\\n            request.selected_approver || \\"\\"\\n        ).trim().toLowerCase();\\n\\n        var loggedInUser = String(\\n            CURRENT_USER || \\"\\"\\n        ).trim().toLowerCase();\\n\\n        if (\\n            selectedUser &&\\n            loggedInUser &&\\n            loggedInUser !== \\"guest\\" &&\\n            selectedUser === loggedInUser\\n        ) {\\n            return true;\\n        }\\n\\n        if (\\n            typeof SUPER_APPROVERS !==\\n                \\"undefined\\" &&\\n\\n            SUPER_APPROVERS.map(function (user) {\\n                return String(\\n                    user || \\"\\"\\n                ).trim().toLowerCase();\\n            }).indexOf(\\n                loggedInUser\\n            ) >= 0\\n        ) {\\n            return true;\\n        }\\n\\n        return false;\\n    }\\n\\n\\n    function requestSummary(request) {\\n\\n        var level =\\n            request.approval_level || \\"L1\\";\\n\\n        var requestedFinal =\\n            parseFloat(\\n                request.requested_final_amount || 0\\n            );\\n\\n        if (\\n            level === \\"L4\\" ||\\n            requestedFinal > 0\\n        ) {\\n            return (\\n                level +\\n                \\" · Final \\" +\\n                fmtM(requestedFinal)\\n            );\\n        }\\n\\n        return (\\n            level +\\n            \\" · \\" +\\n            parseFloat(\\n                request.requested_discount_pct || 0\\n            ) +\\n            \\"%\\"\\n        );\\n    }\\n\\n\\n    function setExactGlobals() {\\n\\n        BILL_DOC =\\n    directInvoiceDoc || {\\n        name:directInvoice\\n    };\\n\\n/*\\n * Do NOT replace the complete L1/L2/L3/L4 chain\\n * with only the request opened from email.\\n */\\nBILL_REQS =\\n    Array.isArray(BILL_REQS)\\n        ? BILL_REQS\\n        : [];\\n\\n/*\\n * Keep/update this exact request only until the complete\\n * sibling history is refreshed from the backend.\\n */\\nvar directIndex = -1;\\n\\nfor(var i=0;i<BILL_REQS.length;i++){\\n\\n    if(\\n        BILL_REQS[i] &&\\n        BILL_REQS[i].name === directRequest.name\\n    ){\\n        directIndex=i;\\n        break;\\n    }\\n}\\n\\nif(directIndex>=0){\\n\\n    BILL_REQS[directIndex]=\\n        directRequest;\\n\\n}else{\\n\\n    BILL_REQS.push(\\n        directRequest\\n    );\\n}\\n    }\\n\\n\\n    function renderActionBar() {\\n\\n        removeElement(\\n            \\"life-email-bill-actions\\"\\n        );\\n\\n        if (\\n            !directRequest ||\\n            !isAuthorized(directRequest)\\n        ) {\\n            return;\\n        }\\n\\n        var actionBar =\\n            document.createElement(\\"div\\");\\n\\n        actionBar.id =\\n            \\"life-email-bill-actions\\";\\n\\n        actionBar.innerHTML =\\n            \'<div class=\\"life-email-action-summary\\">\' +\\n                \\"<span>\\" +\\n                    esc(directInvoice) +\\n                \\"</span>\\" +\\n                \\"<span>\\" +\\n                    esc(\\n                        requestSummary(\\n                            directRequest\\n                        )\\n                    ) +\\n                \\"</span>\\" +\\n            \\"</div>\\" +\\n\\n            \'<button type=\\"button\\" \' +\\n            \'id=\\"life-email-approve\\" \' +\\n            \'class=\\"life-email-action-button\\">\' +\\n                \\"✓ Approve\\" +\\n            \\"</button>\\" +\\n\\n            \'<button type=\\"button\\" \' +\\n            \'id=\\"life-email-reject\\" \' +\\n            \'class=\\"life-email-action-button\\">\' +\\n                \\"✕ Reject\\" +\\n            \\"</button>\\";\\n\\n        document.body.appendChild(\\n            actionBar\\n        );\\n\\n        document.getElementById(\\n            \\"life-email-approve\\"\\n        ).onclick = function () {\\n\\n            setExactGlobals();\\n\\n            billApprove(\\n                directRequest.name\\n            );\\n        };\\n\\n        document.getElementById(\\n            \\"life-email-reject\\"\\n        ).onclick = function () {\\n\\n            setExactGlobals();\\n\\n            billReject(\\n                directRequest.name\\n            );\\n        };\\n    }\\n\\n\\n    function openExactBill(\\n        invoiceName,\\n        requestName\\n    ) {\\n\\n        showLoader();\\n\\n        /*\\n         * First load the exact approval request.\\n         */\\n        /*\\n         * Resolve the authenticated ERPNext user directly from\\n         * the server before checking the selected approver.\\n         */\\n        call(\\n            \\"frappe.auth.get_logged_user\\",\\n            {}\\n        )\\n\\n        .then(function (authenticatedUser) {\\n\\n            var resolvedUser = \\"\\";\\n\\n            if (\\n                typeof authenticatedUser === \\"string\\"\\n            ) {\\n                resolvedUser =\\n                    authenticatedUser;\\n            }\\n\\n            else if (\\n                authenticatedUser &&\\n                authenticatedUser.user\\n            ) {\\n                resolvedUser =\\n                    authenticatedUser.user;\\n            }\\n\\n            else if (\\n                authenticatedUser &&\\n                authenticatedUser.message\\n            ) {\\n                resolvedUser =\\n                    authenticatedUser.message;\\n            }\\n\\n            resolvedUser = String(\\n                resolvedUser || \\"\\"\\n            ).trim();\\n\\n            if (\\n                !resolvedUser ||\\n                resolvedUser === \\"Guest\\"\\n            ) {\\n                throw new Error(\\n                    \\"Your ERP login session could not be verified. \\" +\\n                    \\"Please sign in again.\\"\\n                );\\n            }\\n\\n            CURRENT_USER =\\n                resolvedUser;\\n\\n            return getDoc(\\n                \\"Discount Approval Request\\",\\n                requestName\\n            );\\n        })\\n\\n        .then(function (request) {\\n\\n            if (!request) {\\n                throw new Error(\\n                    \\"Approval request was not found.\\"\\n                );\\n            }\\n\\n            if (\\n                request.linked_invoice !==\\n                invoiceName\\n            ) {\\n                throw new Error(\\n                    \\"Approval request and invoice do not match.\\"\\n                );\\n            }\\n\\n            if (\\n                request.status !== \\"Pending\\"\\n            ) {\\n                throw new Error(\\n                    \\"This request is already \\" +\\n                    request.status +\\n                    \\".\\"\\n                );\\n            }\\n\\n            if (!isAuthorized(request)) {\\n                throw new Error(\\n                    \\"You are not the selected approver.\\"\\n                );\\n            }\\n\\n            directRequest =\\n                request;\\n\\n            return getDoc(\\n                \\"Sales Invoice\\",\\n                invoiceName\\n            );\\n        })\\n\\n        .then(function (invoiceDocument) {\\n\\n            directInvoiceDoc =\\n                invoiceDocument || {\\n                    name:invoiceName\\n                };\\n\\n            setExactGlobals();\\n\\n            document.documentElement.classList.add(\\n                \\"life-email-bill-mode\\"\\n            );\\n\\n            /*\\n             * Open exact bill directly.\\n             * Do not open the Discount Approvals list.\\n             */\\n            openBill(invoiceName);\\n\\n            setTimeout(function () {\\n\\n                /*\\n                 * openBill loads all approval history.\\n                 * Reset action variables to exact email request.\\n                 */\\n                setExactGlobals();\\n\\n                removeElement(\\n                    \\"life-email-bill-loader\\"\\n                );\\n\\n                renderActionBar();\\n\\n                var billModal =\\n                    _g(\\"m-bill\\");\\n\\n                if (billModal) {\\n                    var modalBody =\\n                        billModal.querySelector(\\n                            \\".m-body\\"\\n                        );\\n\\n                    if (modalBody) {\\n                        modalBody.scrollTop = 0;\\n                    }\\n                }\\n\\n            }, 900);\\n        })\\n\\n        .catch(function (error) {\\n\\n            document.documentElement.classList.remove(\\n                \\"life-email-bill-mode\\"\\n            );\\n\\n            var message =\\n                error &&\\n                error.message\\n                    ? error.message\\n                    : serverErr(error);\\n\\n            showError(message);\\n        });\\n    }\\n\\n\\n    function startDirectEmailBill() {\\n\\n        if (directStarted) {\\n            return true;\\n        }\\n\\n        var parameters =\\n            getEmailParameters();\\n\\n        if (\\n            !parameters.invoice ||\\n            !parameters.request\\n        ) {\\n            return false;\\n        }\\n\\n        if (\\n            typeof getDoc !== \\"function\\" ||\\n            typeof openBill !== \\"function\\" ||\\n            typeof billApprove !== \\"function\\" ||\\n            typeof billReject !== \\"function\\" ||\\n            typeof CURRENT_USER === \\"undefined\\" ||\\n            !CURRENT_USER ||\\n            CURRENT_USER === \\"Guest\\"\\n        ) {\\n            return false;\\n        }\\n\\n        directStarted = true;\\n\\n        directInvoice =\\n            parameters.invoice;\\n\\n        openExactBill(\\n            parameters.invoice,\\n            parameters.request\\n        );\\n\\n        return true;\\n    }\\n\\n\\n    /*\\n     * Show loader early when this URL is from an approval email.\\n     */\\n    var initialParameters =\\n        getEmailParameters();\\n\\n    if (\\n        initialParameters.invoice &&\\n        initialParameters.request\\n    ) {\\n        if (document.body) {\\n            showLoader();\\n        } else {\\n            document.addEventListener(\\n                \\"DOMContentLoaded\\",\\n                showLoader\\n            );\\n        }\\n    }\\n\\n\\n    /*\\n     * Wait until the Billing module finishes loading.\\n     */\\n    var attempts = 0;\\n\\n    var startTimer =\\n        setInterval(function () {\\n\\n            attempts += 1;\\n\\n            if (startDirectEmailBill()) {\\n                clearInterval(\\n                    startTimer\\n                );\\n            }\\n\\n            if (attempts >= 160) {\\n\\n                clearInterval(\\n                    startTimer\\n                );\\n\\n                if (!directStarted) {\\n                    removeElement(\\n                        \\"life-email-bill-loader\\"\\n                    );\\n                }\\n            }\\n\\n        }, 250);\\n\\n})();\\n\\n<\\\\/script>\\n\\n\\n<script id=\\"life-billing-url-sync-v10-script\\">\\n\\n(function () {\\n\\n    if (window.__lifeBillingUrlSyncV10) {\\n        return;\\n    }\\n\\n    window.__lifeBillingUrlSyncV10 = true;\\n\\n\\n    function getTargetWindow() {\\n\\n        try {\\n            if (\\n                window.parent &&\\n                window.parent !== window &&\\n                window.parent.history &&\\n                window.parent.location\\n            ) {\\n                return window.parent;\\n            }\\n        } catch (error) {}\\n\\n        return window;\\n    }\\n\\n\\n    function cleanViewName(viewName) {\\n\\n        var allowed = [\\n            \\"billing\\",\\n            \\"recent\\",\\n            \\"pending\\",\\n            \\"collections\\",\\n            \\"approvals\\"\\n        ];\\n\\n        if (\\n            allowed.indexOf(viewName) < 0\\n        ) {\\n            return \\"billing\\";\\n        }\\n\\n        return viewName;\\n    }\\n\\n\\n    function updatePortalUrl(viewName) {\\n\\n        viewName =\\n            cleanViewName(viewName);\\n\\n        var targetWindow =\\n            getTargetWindow();\\n\\n        var targetPath;\\n\\n        /*\\n         * Billing inside life-home:\\n         * update the parent portal URL.\\n         */\\n        if (\\n            targetWindow.location.pathname\\n                .indexOf(\\"/life-home\\") >= 0\\n        ) {\\n            targetPath =\\n                \\"/life-home\\" +\\n                \\"?view=billing\\" +\\n                \\"&billing_view=\\" +\\n                encodeURIComponent(viewName);\\n        }\\n\\n        /*\\n         * Direct billing-v2:\\n         * keep billing-v2 as the route.\\n         */\\n        else {\\n            targetPath =\\n                \\"/billing-v2\\" +\\n                \\"?view=\\" +\\n                encodeURIComponent(viewName);\\n        }\\n\\n        /*\\n         * invoice and request parameters are intentionally removed.\\n         */\\n        targetWindow.history.replaceState(\\n            {\\n                lifeBillingView:viewName\\n            },\\n            \\"\\",\\n            targetPath\\n        );\\n    }\\n\\n\\n    function currentBillingView() {\\n\\n        if (\\n            typeof ACTIVE_VIEW !== \\"undefined\\" &&\\n            ACTIVE_VIEW\\n        ) {\\n            return cleanViewName(\\n                ACTIVE_VIEW\\n            );\\n        }\\n\\n        var activeButton =\\n            document.querySelector(\\n                \\".nav-pill.active[data-v]\\"\\n            );\\n\\n        if (activeButton) {\\n            return cleanViewName(\\n                activeButton.getAttribute(\\n                    \\"data-v\\"\\n                )\\n            );\\n        }\\n\\n        return \\"billing\\";\\n    }\\n\\n\\n    function bindTabUrlUpdates() {\\n\\n        var buttons =\\n            document.querySelectorAll(\\n                \\".nav-pill[data-v]\\"\\n            );\\n\\n        Array.prototype.forEach.call(\\n            buttons,\\n            function (button) {\\n\\n                if (\\n                    button.getAttribute(\\n                        \\"data-life-url-bound\\"\\n                    ) === \\"1\\"\\n                ) {\\n                    return;\\n                }\\n\\n                button.setAttribute(\\n                    \\"data-life-url-bound\\",\\n                    \\"1\\"\\n                );\\n\\n                button.addEventListener(\\n                    \\"click\\",\\n                    function () {\\n\\n                        var selectedView =\\n                            button.getAttribute(\\n                                \\"data-v\\"\\n                            ) || \\"billing\\";\\n\\n                        /*\\n                         * Let the existing showView() finish first.\\n                         */\\n                        setTimeout(function () {\\n                            updatePortalUrl(\\n                                selectedView\\n                            );\\n                        }, 30);\\n                    }\\n                );\\n            }\\n        );\\n    }\\n\\n\\n    function emailParametersExist() {\\n\\n        var locations = [];\\n\\n        try {\\n            locations.push(\\n                window.location.search || \\"\\"\\n            );\\n        } catch (error) {}\\n\\n        try {\\n            if (\\n                window.parent &&\\n                window.parent !== window\\n            ) {\\n                locations.push(\\n                    window.parent.location.search || \\"\\"\\n                );\\n            }\\n        } catch (error) {}\\n\\n        var combined =\\n            locations.join(\\"&\\");\\n\\n        return (\\n            combined.indexOf(\\"invoice=\\") >= 0 &&\\n            combined.indexOf(\\"request=\\") >= 0\\n        );\\n    }\\n\\n\\n    function cleanUrlAfterBillOpens() {\\n\\n        if (!emailParametersExist()) {\\n            return;\\n        }\\n\\n        var attempts = 0;\\n\\n        var modalTimer =\\n            setInterval(function () {\\n\\n                attempts += 1;\\n\\n                var billModal =\\n                    document.getElementById(\\n                        \\"m-bill\\"\\n                    );\\n\\n                var modalOpen = false;\\n\\n                if (billModal) {\\n                    modalOpen = (\\n                        billModal.classList.contains(\\n                            \\"show\\"\\n                        ) ||\\n                        window.getComputedStyle(\\n                            billModal\\n                        ).display !== \\"none\\"\\n                    );\\n                }\\n\\n                if (modalOpen) {\\n\\n                    clearInterval(\\n                        modalTimer\\n                    );\\n\\n                    /*\\n                     * The exact bill is already open.\\n                     * The email parameters are no longer needed.\\n                     */\\n                    updatePortalUrl(\\n                        currentBillingView()\\n                    );\\n                }\\n\\n                if (attempts >= 100) {\\n                    clearInterval(\\n                        modalTimer\\n                    );\\n                }\\n\\n            }, 200);\\n    }\\n\\n\\n    function startUrlSync() {\\n\\n        bindTabUrlUpdates();\\n        cleanUrlAfterBillOpens();\\n\\n        /*\\n         * Rebind if the navigation is rendered again.\\n         */\\n        var observer =\\n            new MutationObserver(function () {\\n                bindTabUrlUpdates();\\n            });\\n\\n        observer.observe(\\n            document.body,\\n            {\\n                childList:true,\\n                subtree:true\\n            }\\n        );\\n    }\\n\\n\\n    if (document.body) {\\n        startUrlSync();\\n    } else {\\n        document.addEventListener(\\n            \\"DOMContentLoaded\\",\\n            startUrlSync\\n        );\\n    }\\n\\n})();\\n\\n<\\\\/script>\\n\\n\\n<style id=\\"life-email-recent-level-actions-v11-style\\">\\n\\n/*\\n * V5 floating buttons are not required.\\n */\\n#life-email-bill-actions {\\n    display:none !important;\\n}\\n\\n\\n/* ================================================================\\n   MOBILE\\n   ================================================================ */\\n\\n@media (max-width:700px) {\\n\\n    /*\\n     * Show native actions inside Level cell.\\n     * This overrides V5\'s native-button hiding rule.\\n     */\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell\\n    button[onclick*=\\"billApprove\\"],\\n\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell\\n    button[onclick*=\\"billReject\\"] {\\n        display:flex !important;\\n        align-items:center !important;\\n        justify-content:center !important;\\n\\n        width:100% !important;\\n        min-height:43px !important;\\n\\n        margin:0 !important;\\n        padding:8px 10px !important;\\n\\n        border-radius:9px !important;\\n        font-size:13px !important;\\n        font-weight:900 !important;\\n        white-space:nowrap !important;\\n    }\\n\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell\\n    button[onclick*=\\"billApprove\\"] {\\n        color:#ffffff !important;\\n        background:linear-gradient(\\n            135deg,\\n            #0b6b4a,\\n            #16a34a\\n        ) !important;\\n        border:0 !important;\\n    }\\n\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell\\n    button[onclick*=\\"billReject\\"] {\\n        color:#b91c1c !important;\\n        background:#ffffff !important;\\n        border:2px solid #dc2626 !important;\\n    }\\n\\n    /*\\n     * Inline action wrapper generated by renderBillDrawer.\\n     */\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell > div:last-child {\\n        display:grid !important;\\n        grid-template-columns:1fr !important;\\n        gap:7px !important;\\n\\n        width:100% !important;\\n        margin-top:10px !important;\\n    }\\n\\n    /*\\n     * Make Level column clear and wide enough.\\n     */\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell {\\n        min-width:145px !important;\\n        padding:12px !important;\\n\\n        color:#053b2a !important;\\n        background:#f0fdf4 !important;\\n        border:1px solid #a7e3c4 !important;\\n        border-radius:10px !important;\\n\\n        overflow:visible !important;\\n        vertical-align:top !important;\\n        white-space:normal !important;\\n    }\\n\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell > b {\\n        display:block !important;\\n        color:#053b2a !important;\\n        font-size:17px !important;\\n        font-weight:900 !important;\\n    }\\n\\n    html.life-email-bill-mode\\n    #m-bill\\n    .life-level-action-cell > div:first-of-type {\\n        margin-top:2px !important;\\n        color:#5f8272 !important;\\n        font-size:11px !important;\\n        font-weight:700 !important;\\n    }\\n\\n    /*\\n     * Mobile workflow table remains horizontally scrollable,\\n     * but actions are in the first visible column.\\n     */\\n    html.life-email-bill-mode\\n    #m-bill .tbl {\\n        overflow-x:auto !important;\\n    }\\n\\n    html.life-email-bill-mode\\n    #m-bill .m-body {\\n        padding-bottom:35px !important;\\n    }\\n}\\n\\n</style>\\n\\n<script id=\\"life-email-recent-level-actions-v11-script\\">\\n\\n(function () {\\n\\n    var parameters =\\n        new URLSearchParams(\\n            window.location.search || \\"\\"\\n        );\\n\\n    var invoiceName =\\n        parameters.get(\\"invoice\\") || \\"\\";\\n\\n    var requestName =\\n        parameters.get(\\"request\\") || \\"\\";\\n\\n    if (\\n        !invoiceName ||\\n        !requestName\\n    ) {\\n        return;\\n    }\\n\\n\\n    /*\\n     * Email route always opens Recent Bills first.\\n     * V5 then opens the particular invoice automatically.\\n     */\\n    try {\\n        localStorage.setItem(\\n            \\"life_billing_active_view_v1\\",\\n            \\"recent\\"\\n        );\\n    } catch (error) {}\\n\\n\\n    /*\\n     * After the particular invoice opens, remove only the\\n     * invoice/request parameters. Keep view=recent.\\n     */\\n    var attempts = 0;\\n\\n    var cleanTimer =\\n        setInterval(function () {\\n\\n            attempts += 1;\\n\\n            var modal =\\n                document.getElementById(\\n                    \\"m-bill\\"\\n                );\\n\\n            var modalOpen = false;\\n\\n            if (modal) {\\n                modalOpen = (\\n                    modal.classList.contains(\\"show\\") ||\\n                    window.getComputedStyle(\\n                        modal\\n                    ).display !== \\"none\\"\\n                );\\n            }\\n\\n            if (modalOpen) {\\n\\n                clearInterval(\\n                    cleanTimer\\n                );\\n\\n                window.history.replaceState(\\n                    {\\n                        lifeBillingView:\\"recent\\"\\n                    },\\n                    \\"\\",\\n                    \\"/billing-v2?view=recent\\"\\n                );\\n            }\\n\\n            if (attempts >= 100) {\\n                clearInterval(\\n                    cleanTimer\\n                );\\n            }\\n\\n        }, 200);\\n\\n})();\\n\\n<\\\\/script>\\n\\n\\n<style id=\\"life-billing-offer-doctor-v1-style\\">\\n.life-doctor-field {\\n    position: relative;\\n    min-width: 230px;\\n}\\n.life-doctor-field .tp-dd {\\n    top: calc(100% - 2px);\\n    z-index: 700;\\n}\\n#life-doctor-selected {\\n    min-height: 18px;\\n    margin-top: 4px;\\n    color: var(--g1);\\n    font-size: 11.5px;\\n    font-weight: 800;\\n}\\n</style>\\n\\n<script id=\\"life-billing-offer-doctor-v1-script\\">\\n(function () {\\n    if (window.__lifeBillingOfferDoctorV1) return;\\n    window.__lifeBillingOfferDoctorV1 = true;\\n\\n    function el(id) {\\n        return document.getElementById(id);\\n    }\\n\\n    function val(id) {\\n        var node = el(id);\\n        return node ? String(node.value || \\"\\").trim() : \\"\\";\\n    }\\n\\n    function normalise(value) {\\n        value = String(value || \\"\\")\\n            .trim()\\n            .toLowerCase()\\n            .replace(/[^a-z0-9]/g, \\"\\");\\n\\n        if (value === \\"himayathnagar\\") return \\"himayatnagar\\";\\n        if (value === \\"chandhanagar\\") return \\"chandanagar\\";\\n\\n        return value;\\n    }\\n\\n    function isDoctor(practitioner) {\\n        var designation = String(\\n            practitioner.designation || \\"\\"\\n        ).toLowerCase();\\n\\n        return (\\n            designation.indexOf(\\"doctor\\") >= 0 ||\\n            designation.indexOf(\\"dermat\\") >= 0 ||\\n            designation.indexOf(\\"physician\\") >= 0 ||\\n            designation.indexOf(\\"medical officer\\") >= 0\\n        );\\n    }\\n\\n    function doctorsForSelectedBranch() {\\n        var selectedBranch = normalise(val(\\"bl-branch\\"));\\n\\n        var doctors = (\\n            typeof PRACTITIONERS !== \\"undefined\\"\\n                ? PRACTITIONERS\\n                : []\\n        ).filter(function (practitioner) {\\n            /*\\n             * Strict branch filtering:\\n             * custom_available_all_branches is intentionally ignored.\\n             */\\n            return (\\n                isDoctor(practitioner) &&\\n                normalise(practitioner.branch) === selectedBranch\\n            );\\n        });\\n\\n        if (typeof dedupePractitioners === \\"function\\") {\\n            doctors = dedupePractitioners(doctors);\\n        }\\n\\n        doctors.sort(function (left, right) {\\n            return String(\\n                left.practitioner_name || left.name || \\"\\"\\n            ).localeCompare(\\n                String(right.practitioner_name || right.name || \\"\\")\\n            );\\n        });\\n\\n        return doctors;\\n    }\\n\\n    function clearDoctor() {\\n        if (el(\\"life-doctor-id\\")) {\\n            el(\\"life-doctor-id\\").value = \\"\\";\\n        }\\n\\n        if (el(\\"life-doctor-name\\")) {\\n            el(\\"life-doctor-name\\").value = \\"\\";\\n        }\\n\\n        if (el(\\"life-doctor-search\\")) {\\n            el(\\"life-doctor-search\\").value = \\"\\";\\n        }\\n\\n        if (el(\\"life-doctor-selected\\")) {\\n            el(\\"life-doctor-selected\\").innerHTML = \\"\\";\\n        }\\n\\n        if (el(\\"life-doctor-dd\\")) {\\n            el(\\"life-doctor-dd\\").classList.remove(\\"show\\");\\n        }\\n    }\\n\\n    function renderDoctors() {\\n        var dropdown = el(\\"life-doctor-dd\\");\\n        var input = el(\\"life-doctor-search\\");\\n\\n        if (!dropdown || !input) return;\\n\\n        var query = String(input.value || \\"\\")\\n            .trim()\\n            .toLowerCase();\\n\\n        var doctors = doctorsForSelectedBranch();\\n\\n        if (query) {\\n            doctors = doctors.filter(function (doctor) {\\n                var searchText = (\\n                    String(doctor.practitioner_name || \\"\\") +\\n                    \\" \\" +\\n                    String(doctor.name || \\"\\") +\\n                    \\" \\" +\\n                    String(doctor.designation || \\"\\")\\n                ).toLowerCase();\\n\\n                return searchText.indexOf(query) >= 0;\\n            });\\n        }\\n\\n        doctors = doctors.slice(0, 50);\\n\\n        if (!doctors.length) {\\n            dropdown.innerHTML =\\n                \'<div class=\\"tp-dd-item\\">\' +\\n                \\"No active doctor found for \\" +\\n                (typeof esc === \\"function\\"\\n                    ? esc(val(\\"bl-branch\\"))\\n                    : val(\\"bl-branch\\")) +\\n                \\"</div>\\";\\n\\n            dropdown.classList.add(\\"show\\");\\n            return;\\n        }\\n\\n        dropdown.innerHTML = doctors.map(function (doctor) {\\n            var doctorName =\\n                doctor.practitioner_name || doctor.name;\\n\\n            return (\\n                \'<div class=\\"tp-dd-item\\" \' +\\n                \'data-doctor-id=\\"\' +\\n                esc(doctor.name) +\\n                \'\\" data-doctor-name=\\"\' +\\n                esc(doctorName) +\\n                \'\\">\' +\\n                \\"<span><b>\\" +\\n                esc(doctorName) +\\n                \\"</b>\\" +\\n                \'<span style=\\"display:block;font-size:10px;color:var(--txt3)\\">\' +\\n                esc(doctor.designation || \\"Doctor\\") +\\n                \\" · \\" +\\n                esc(doctor.branch || \\"\\") +\\n                \\"</span></span></div>\\"\\n            );\\n        }).join(\\"\\");\\n\\n        dropdown.classList.add(\\"show\\");\\n\\n        Array.prototype.forEach.call(\\n            dropdown.querySelectorAll(\\"[data-doctor-id]\\"),\\n            function (option) {\\n                option.onclick = function () {\\n                    var id = option.getAttribute(\\"data-doctor-id\\");\\n                    var name =\\n                        option.getAttribute(\\"data-doctor-name\\");\\n\\n                    el(\\"life-doctor-id\\").value = id;\\n                    el(\\"life-doctor-name\\").value = name;\\n                    el(\\"life-doctor-search\\").value = name;\\n                    el(\\"life-doctor-selected\\").innerHTML =\\n                        \\"✓ \\" + esc(name);\\n\\n                    dropdown.classList.remove(\\"show\\");\\n                };\\n            }\\n        );\\n    }\\n\\n    function insertDoctorField() {\\n        if (el(\\"life-doctor-search\\")) return;\\n\\n        var consultantInput = el(\\"bl-prac-search\\");\\n        if (!consultantInput || !consultantInput.parentElement) {\\n            return;\\n        }\\n\\n        var wrapper = document.createElement(\\"div\\");\\n        wrapper.className = \\"life-doctor-field\\";\\n\\n        wrapper.innerHTML =\\n            \'<label class=\\"f-lbl\\">\' +\\n            \'Doctor Consultant \' +\\n            \'<span style=\\"color:var(--txt4);font-size:10px\\">\' +\\n            \\"(Optional)</span></label>\\" +\\n            \'<input class=\\"f-inp\\" id=\\"life-doctor-search\\" \' +\\n            \'placeholder=\\"Search doctor from selected branch…\\" \' +\\n            \'autocomplete=\\"off\\">\' +\\n            \'<input type=\\"hidden\\" id=\\"life-doctor-id\\">\' +\\n            \'<input type=\\"hidden\\" id=\\"life-doctor-name\\">\' +\\n            \'<div class=\\"tp-dd\\" id=\\"life-doctor-dd\\"></div>\' +\\n            \'<div id=\\"life-doctor-selected\\"></div>\';\\n\\n        consultantInput.parentElement.insertAdjacentElement(\\n            \\"afterend\\",\\n            wrapper\\n        );\\n\\n        el(\\"life-doctor-search\\").addEventListener(\\n            \\"focus\\",\\n            renderDoctors\\n        );\\n\\n        el(\\"life-doctor-search\\").addEventListener(\\n            \\"input\\",\\n            function () {\\n                if (el(\\"life-doctor-id\\")) {\\n                    el(\\"life-doctor-id\\").value = \\"\\";\\n                }\\n\\n                if (el(\\"life-doctor-name\\")) {\\n                    el(\\"life-doctor-name\\").value = \\"\\";\\n                }\\n\\n                if (el(\\"life-doctor-selected\\")) {\\n                    el(\\"life-doctor-selected\\").innerHTML = \\"\\";\\n                }\\n\\n                renderDoctors();\\n            }\\n        );\\n\\n        var branch = el(\\"bl-branch\\");\\n\\n        if (\\n            branch &&\\n            branch.getAttribute(\\"data-life-doctor-bound\\") !== \\"1\\"\\n        ) {\\n            branch.setAttribute(\\n                \\"data-life-doctor-bound\\",\\n                \\"1\\"\\n            );\\n\\n            branch.addEventListener(\\"change\\", clearDoctor);\\n        }\\n    }\\n\\n    /*\\n     * The live bootstrap currently returns only the first child item\\n     * from PRLE-0389. Expand that same valid rule to Hair PRP and\\n     * Skin PRP inside this new webpage.\\n     */\\n    function fixPrpOffers() {\\n        if (\\n            typeof OFFERS === \\"undefined\\" ||\\n            !Array.isArray(OFFERS)\\n        ) {\\n            return;\\n        }\\n\\n        var prpRule = null;\\n\\n        OFFERS.forEach(function (offer) {\\n            if (\\n                offer.name === \\"PRLE-0389\\" ||\\n                (\\n                    String(offer.title || \\"\\")\\n                        .toLowerCase()\\n                        .indexOf(\\"prp special offer\\") >= 0 &&\\n                    parseFloat(offer.rate || 0) === 3999\\n                )\\n            ) {\\n                prpRule = offer;\\n            }\\n        });\\n\\n        if (!prpRule) return;\\n\\n        [\\"Hair PRP\\", \\"Skin PRP\\"].forEach(function (itemCode) {\\n            var exists = OFFERS.some(function (offer) {\\n                return (\\n                    offer.name === prpRule.name &&\\n                    String(offer.item_code || \\"\\").trim() === itemCode\\n                );\\n            });\\n\\n            if (!exists) {\\n                var copiedRule = {};\\n\\n                Object.keys(prpRule).forEach(function (key) {\\n                    copiedRule[key] = prpRule[key];\\n                });\\n\\n                copiedRule.item_code = itemCode;\\n                copiedRule.apply_on = \\"Item Code\\";\\n                copiedRule.price_or_product_discount = \\"Price\\";\\n                copiedRule.rate = 3999;\\n\\n                OFFERS.push(copiedRule);\\n            }\\n        });\\n    }\\n\\n    function connectPayload() {\\n        if (\\n            typeof billPayload !== \\"function\\" ||\\n            billPayload.__lifeDoctorConnected\\n        ) {\\n            return;\\n        }\\n\\n        var originalBillPayload = billPayload;\\n\\n        billPayload = function () {\\n            var payload = originalBillPayload.apply(\\n                this,\\n                arguments\\n            );\\n\\n            payload.doctor_practitioner =\\n                val(\\"life-doctor-id\\");\\n\\n            payload.doctor_name =\\n                val(\\"life-doctor-name\\");\\n\\n            return payload;\\n        };\\n\\n        billPayload.__lifeDoctorConnected = true;\\n    }\\n\\n    function initialise() {\\n        fixPrpOffers();\\n        insertDoctorField();\\n        connectPayload();\\n\\n        var observer = new MutationObserver(function () {\\n            fixPrpOffers();\\n            insertDoctorField();\\n            connectPayload();\\n        });\\n\\n        observer.observe(document.body, {\\n            childList: true,\\n            subtree: true\\n        });\\n\\n        document.addEventListener(\\"click\\", function (event) {\\n            if (\\n                !event.target.closest(\\".life-doctor-field\\") &&\\n                el(\\"life-doctor-dd\\")\\n            ) {\\n                el(\\"life-doctor-dd\\").classList.remove(\\"show\\");\\n            }\\n        });\\n    }\\n\\n    if (document.body) {\\n        initialise();\\n    } else {\\n        document.addEventListener(\\n            \\"DOMContentLoaded\\",\\n            initialise\\n        );\\n    }\\n})();\\n<\\\\/script>\\n\\n\\n<style id=\\"life-duplicate-offer-v2-style\\">\\n.life-duplicate-therapy {\\n    border-color:#dc2626 !important;\\n    background:#fff7f7 !important;\\n    box-shadow:0 0 0 3px rgba(220,38,38,.10) !important;\\n}\\n.life-offer-loading {\\n    padding:8px 10px;\\n    margin-bottom:8px;\\n    border:1px dashed #f59e0b;\\n    border-radius:8px;\\n    background:#fffbeb;\\n    color:#92400e;\\n    font-size:11px;\\n    font-weight:700;\\n}\\n</style>\\n\\n<script id=\\"life-duplicate-offer-v2-script\\">\\n(function () {\\n    if (window.__lifeDuplicateOfferV2) return;\\n    window.__lifeDuplicateOfferV2 = true;\\n\\n    var pricingRulesLoaded = false;\\n    var pricingRulesLoading = false;\\n\\n    function node(id) {\\n        return document.getElementById(id);\\n    }\\n\\n    function clean(value) {\\n        return String(value || \\"\\")\\n            .trim()\\n            .toLowerCase()\\n            .replace(/\\\\\\\\s+/g, \\" \\");\\n    }\\n\\n    function showMessage(message, colour) {\\n        if (typeof alertMsg === \\"function\\") {\\n            alertMsg(message, colour || \\"red\\");\\n        } else if (typeof frappe !== \\"undefined\\") {\\n            frappe.msgprint(message);\\n        }\\n    }\\n\\n    function selectedTherapies(excludeRow) {\\n        var selected = [];\\n\\n        document.querySelectorAll(\\n            \\"#bl-lines .tp-row\\"\\n        ).forEach(function (row) {\\n            if (row === excludeRow) return;\\n\\n            var input = row.querySelector(\\".tp-search\\");\\n            var therapy = clean(input ? input.value : \\"\\");\\n\\n            if (therapy) selected.push(therapy);\\n        });\\n\\n        return selected;\\n    }\\n\\n    function therapyAlreadySelected(therapy, currentRow) {\\n        therapy = clean(therapy);\\n\\n        if (!therapy) return false;\\n\\n        return selectedTherapies(currentRow)\\n            .indexOf(therapy) >= 0;\\n    }\\n\\n    function clearDuplicateRow(row) {\\n        if (!row) return;\\n\\n        var index = parseInt(\\n            row.getAttribute(\\"data-i\\"),\\n            10\\n        );\\n\\n        var search = row.querySelector(\\".tp-search\\");\\n        var quantity = row.querySelector(\\".tp-qty\\");\\n        var rate = row.querySelector(\\".tp-rate\\");\\n        var amount = row.querySelector(\\".tp-amt\\");\\n        var range = row.querySelector(\\".tp-range\\");\\n        var category = row.querySelector(\\".tp-cat\\");\\n        var offer = row.querySelector(\\".tp-offer\\");\\n\\n        if (search) {\\n            search.value = \\"\\";\\n            search.classList.add(\\"life-duplicate-therapy\\");\\n\\n            setTimeout(function () {\\n                search.classList.remove(\\n                    \\"life-duplicate-therapy\\"\\n                );\\n                search.focus();\\n            }, 1000);\\n        }\\n\\n        if (quantity) quantity.value = 1;\\n        if (rate) {\\n            rate.value = 0;\\n            rate.disabled = false;\\n        }\\n        if (amount) amount.value = 0;\\n        if (range) range.innerHTML = \\"—\\";\\n        if (category) category.innerHTML = \\"\\";\\n        if (offer) offer.innerHTML = \\"\\";\\n\\n        if (\\n            typeof BILL !== \\"undefined\\" &&\\n            BILL.lines &&\\n            !isNaN(index) &&\\n            BILL.lines[index]\\n        ) {\\n            BILL.lines[index] = {\\n                therapy:\\"\\",\\n                qty:1,\\n                rate:0\\n            };\\n        }\\n\\n        if (typeof recalc === \\"function\\") {\\n            recalc();\\n        }\\n    }\\n\\n    function validateAllDuplicates(showError) {\\n        var used = {};\\n        var duplicateNames = [];\\n\\n        document.querySelectorAll(\\n            \\"#bl-lines .tp-row\\"\\n        ).forEach(function (row) {\\n            var input = row.querySelector(\\".tp-search\\");\\n            var originalName = String(\\n                input ? input.value : \\"\\"\\n            ).trim();\\n\\n            var key = clean(originalName);\\n\\n            if (!key) return;\\n\\n            if (used[key]) {\\n                duplicateNames.push(originalName);\\n\\n                if (input) {\\n                    input.classList.add(\\n                        \\"life-duplicate-therapy\\"\\n                    );\\n                }\\n            } else {\\n                used[key] = true;\\n\\n                if (input) {\\n                    input.classList.remove(\\n                        \\"life-duplicate-therapy\\"\\n                    );\\n                }\\n            }\\n        });\\n\\n        duplicateNames = duplicateNames.filter(\\n            function (name, index, list) {\\n                return list.indexOf(name) === index;\\n            }\\n        );\\n\\n        if (duplicateNames.length && showError) {\\n            showMessage(\\n                \\"Duplicate Therapy Type is not allowed: \\" +\\n                duplicateNames.join(\\", \\") +\\n                \\". Increase Sessions in the existing row instead.\\",\\n                \\"red\\"\\n            );\\n        }\\n\\n        return duplicateNames.length === 0;\\n    }\\n\\n    /*\\n     * Block duplicate selection before the existing dropdown\\n     * click handler saves it into BILL.lines.\\n     */\\n    document.addEventListener(\\n        \\"click\\",\\n        function (event) {\\n            var option = event.target.closest(\\n                \\"#bl-lines .tp-dd-item[data-n]\\"\\n            );\\n\\n            if (!option) return;\\n\\n            var row = option.closest(\\".tp-row\\");\\n            var therapy = option.getAttribute(\\"data-n\\");\\n\\n            if (therapyAlreadySelected(therapy, row)) {\\n                event.preventDefault();\\n                event.stopPropagation();\\n                event.stopImmediatePropagation();\\n\\n                clearDuplicateRow(row);\\n\\n                showMessage(\\n                    therapy +\\n                    \\" is already selected. Please increase Sessions \\" +\\n                    \\"in the existing row.\\",\\n                    \\"red\\"\\n                );\\n            }\\n        },\\n        true\\n    );\\n\\n    /*\\n     * Also catch a duplicate typed manually.\\n     */\\n    document.addEventListener(\\n        \\"change\\",\\n        function (event) {\\n            if (\\n                !event.target.matches(\\n                    \\"#bl-lines .tp-search\\"\\n                )\\n            ) {\\n                return;\\n            }\\n\\n            var row = event.target.closest(\\".tp-row\\");\\n\\n            if (\\n                therapyAlreadySelected(\\n                    event.target.value,\\n                    row\\n                )\\n            ) {\\n                var therapy = event.target.value;\\n\\n                clearDuplicateRow(row);\\n\\n                showMessage(\\n                    therapy +\\n                    \\" is already selected. Duplicate Therapy Types \\" +\\n                    \\"are not allowed.\\",\\n                    \\"red\\"\\n                );\\n            }\\n        },\\n        true\\n    );\\n\\n    /*\\n     * Final protection before previewing or generating.\\n     */\\n    document.addEventListener(\\n        \\"click\\",\\n        function (event) {\\n            var action = event.target.closest(\\n                \\"#bl-preview, #bl-generate\\"\\n            );\\n\\n            if (!action) return;\\n\\n            if (!validateAllDuplicates(true)) {\\n                event.preventDefault();\\n                event.stopPropagation();\\n                event.stopImmediatePropagation();\\n            }\\n        },\\n        true\\n    );\\n\\n    function uniqueRecords(records) {\\n        var output = [];\\n        var seen = {};\\n\\n        (records || []).forEach(function (record) {\\n            if (!record || !record.name) return;\\n            if (seen[record.name]) return;\\n\\n            seen[record.name] = true;\\n            output.push(record);\\n        });\\n\\n        return output;\\n    }\\n\\n    function pricingRuleIsValid(rule, today) {\\n        if (!rule || parseInt(rule.disable || 0, 10)) {\\n            return false;\\n        }\\n\\n        if (\\n            parseInt(rule.selling || 0, 10) !== 1\\n        ) {\\n            return false;\\n        }\\n\\n        var fromDate = String(\\n            rule.valid_from || \\"\\"\\n        ).slice(0, 10);\\n\\n        var toDate = String(\\n            rule.valid_upto || \\"\\"\\n        ).slice(0, 10);\\n\\n        if (fromDate && fromDate > today) return false;\\n        if (toDate && toDate < today) return false;\\n\\n        return true;\\n    }\\n\\n    function rerenderAllOffers() {\\n        if (\\n            typeof offerCheckRow !== \\"function\\" ||\\n            typeof BILL === \\"undefined\\"\\n        ) {\\n            return;\\n        }\\n\\n        document.querySelectorAll(\\n            \\"#bl-lines .tp-row\\"\\n        ).forEach(function (row) {\\n            var index = parseInt(\\n                row.getAttribute(\\"data-i\\"),\\n                10\\n            );\\n\\n            if (\\n                !isNaN(index) &&\\n                BILL.lines &&\\n                BILL.lines[index] &&\\n                BILL.lines[index].therapy\\n            ) {\\n                offerCheckRow(row, index);\\n            }\\n        });\\n    }\\n\\n    function loadPricingRuleItems(rules) {\\n        /*\\n         * Do not query Pricing Rule Item Code directly.\\n         * Frappe blocks direct child-table get_list calls for\\n         * portal users with check_parent_permission().\\n         *\\n         * Fetch the permitted parent Pricing Rule documents\\n         * and read their items child tables instead.\\n         */\\n\\n        if (\\n            !rules ||\\n            !rules.length ||\\n            typeof getDoc !== \\"function\\"\\n        ) {\\n            return Promise.resolve([]);\\n        }\\n\\n        var requests = rules.map(function (rule) {\\n            return getDoc(\\n                \\"Pricing Rule\\",\\n                rule.name\\n            )\\n\\n            .then(function (document) {\\n                var rows = [];\\n\\n                (document.items || []).forEach(\\n                    function (item) {\\n                        if (!item.item_code) return;\\n\\n                        rows.push({\\n                            parent:document.name,\\n                            item_code:String(\\n                                item.item_code\\n                            ).trim(),\\n                            uom:item.uom || \\"\\",\\n                            idx:parseInt(\\n                                item.idx || 0,\\n                                10\\n                            )\\n                        });\\n                    }\\n                );\\n\\n                return rows;\\n            })\\n\\n            .catch(function (error) {\\n                console.warn(\\n                    \\"[LIFE Billing] Could not read Pricing Rule\\",\\n                    rule.name,\\n                    error\\n                );\\n\\n                return [];\\n            });\\n        });\\n\\n        return Promise.all(requests)\\n            .then(function (results) {\\n                var itemRows = [];\\n\\n                results.forEach(function (rows) {\\n                    (rows || []).forEach(\\n                        function (row) {\\n                            itemRows.push(row);\\n                        }\\n                    );\\n                });\\n\\n                return itemRows;\\n            });\\n    }\\n\\n    function buildOffers(rules, itemRows, today) {\\n        var ruleMap = {};\\n        var offers = [];\\n\\n        rules.forEach(function (rule) {\\n            if (pricingRuleIsValid(rule, today)) {\\n                ruleMap[rule.name] = rule;\\n            }\\n        });\\n\\n        (itemRows || []).forEach(function (itemRow) {\\n            var rule = ruleMap[itemRow.parent];\\n\\n            if (!rule || !itemRow.item_code) return;\\n\\n            offers.push({\\n                name:rule.name,\\n                title:rule.title || rule.name,\\n                apply_on:\\"Item Code\\",\\n                item_code:String(\\n                    itemRow.item_code\\n                ).trim(),\\n                uom:itemRow.uom || \\"\\",\\n                price_or_product_discount:\\n                    rule.price_or_product_discount || \\"Price\\",\\n                rate_or_discount:\\n                    rule.rate_or_discount || \\"\\",\\n                rate:parseFloat(rule.rate || 0),\\n                discount_percentage:parseFloat(\\n                    rule.discount_percentage || 0\\n                ),\\n                discount_amount:parseFloat(\\n                    rule.discount_amount || 0\\n                ),\\n                min_qty:parseFloat(rule.min_qty || 0),\\n                max_qty:parseFloat(rule.max_qty || 0),\\n                valid_from:rule.valid_from || \\"\\",\\n                valid_upto:rule.valid_upto || \\"\\",\\n                priority:parseInt(rule.priority || 0, 10)\\n            });\\n        });\\n\\n        offers.sort(function (left, right) {\\n            var priorityDifference =\\n                parseInt(right.priority || 0, 10) -\\n                parseInt(left.priority || 0, 10);\\n\\n            if (priorityDifference) {\\n                return priorityDifference;\\n            }\\n\\n            return String(right.name).localeCompare(\\n                String(left.name)\\n            );\\n        });\\n\\n        return offers;\\n    }\\n\\n    function loadDynamicPricingRules() {\\n\\n        /*\\n         * IMPORTANT:\\n         * getList() ultimately uses the global call() wrapper.\\n         * Do not start this optional live refresh until Frappe\'s\\n         * request function is genuinely ready.\\n         */\\n        if (\\n            pricingRulesLoaded ||\\n            pricingRulesLoading ||\\n            typeof getList !== \\"function\\" ||\\n            typeof window.frappe === \\"undefined\\" ||\\n            typeof window.frappe.call !== \\"function\\"\\n        ) {\\n            return false;\\n        }\\n\\n        pricingRulesLoading = true;\\n\\n        var today =\\n            typeof frappe !== \\"undefined\\" &&\\n            frappe.datetime &&\\n            frappe.datetime.get_today\\n                ? frappe.datetime.get_today()\\n                : new Date().toISOString().slice(0, 10);\\n\\n        var fields = [\\n            \\"name\\",\\n            \\"title\\",\\n            \\"disable\\",\\n            \\"selling\\",\\n            \\"apply_on\\",\\n            \\"price_or_product_discount\\",\\n            \\"rate_or_discount\\",\\n            \\"rate\\",\\n            \\"discount_percentage\\",\\n            \\"discount_amount\\",\\n            \\"min_qty\\",\\n            \\"max_qty\\",\\n            \\"valid_from\\",\\n            \\"valid_upto\\",\\n            \\"priority\\",\\n            \\"modified\\"\\n        ];\\n\\n        /*\\n         * Query dated and no-start-date rules separately,\\n         * then validate both From Date and To Date again.\\n         */\\n        Promise.all([\\n            getList(\\n                \\"Pricing Rule\\",\\n                [\\n                    [\\"disable\\", \\"=\\", 0],\\n                    [\\"selling\\", \\"=\\", 1],\\n                    [\\"apply_on\\", \\"=\\", \\"Item Code\\"],\\n                    [\\"valid_from\\", \\"<=\\", today]\\n                ],\\n                fields,\\n                {\\n                    limit:0,\\n                    order_by:\\n                        \\"priority desc, modified desc\\"\\n                }\\n            ),\\n\\n            getList(\\n                \\"Pricing Rule\\",\\n                [\\n                    [\\"disable\\", \\"=\\", 0],\\n                    [\\"selling\\", \\"=\\", 1],\\n                    [\\"apply_on\\", \\"=\\", \\"Item Code\\"],\\n                    [\\"valid_from\\", \\"is\\", \\"not set\\"]\\n                ],\\n                fields,\\n                {\\n                    limit:0,\\n                    order_by:\\n                        \\"priority desc, modified desc\\"\\n                }\\n            )\\n        ])\\n\\n        .then(function (result) {\\n            var rules = uniqueRecords(\\n                (result[0] || []).concat(result[1] || [])\\n            ).filter(function (rule) {\\n                return pricingRuleIsValid(rule, today);\\n            });\\n\\n            return loadPricingRuleItems(rules)\\n                .then(function (itemRows) {\\n                    return {\\n                        rules:rules,\\n                        itemRows:itemRows\\n                    };\\n                });\\n        })\\n\\n        .then(function (result) {\\n            var liveOffers = buildOffers(\\n                result.rules,\\n                result.itemRows,\\n                today\\n            );\\n\\n            /*\\n             * Replace bootstrap offers only after the complete\\n             * live Pricing Rule load succeeds.\\n             */\\n            if (liveOffers.length) {\\n                OFFERS = liveOffers;\\n                pricingRulesLoaded = true;\\n                rerenderAllOffers();\\n\\n                console.info(\\n                    \\"[LIFE Billing] Active Pricing Rule offers loaded\\",\\n                    {\\n                        date:today,\\n                        rules:result.rules.length,\\n                        item_offers:liveOffers.length\\n                    }\\n                );\\n            }\\n        })\\n\\n        .catch(function (error) {\\n            /*\\n             * Keep existing bootstrap offers if direct loading fails.\\n             */\\n            console.error(\\n                \\"[LIFE Billing] Pricing Rule load failed\\",\\n                error\\n            );\\n        })\\n\\n        .finally(function () {\\n            pricingRulesLoading = false;\\n        });\\n\\n        return true;\\n    }\\n\\n    /*\\n     * Wait until BOTH the Billing module and Frappe request API\\n     * are ready. Do not clear the timer before the loader actually\\n     * starts.\\n     */\\n    var attempts = 0;\\n\\n    var timer = setInterval(function () {\\n\\n        attempts += 1;\\n\\n        var frappeReady =\\n            typeof window.frappe !== \\"undefined\\" &&\\n            typeof window.frappe.call === \\"function\\";\\n\\n        var billingReady =\\n            typeof OFFERS !== \\"undefined\\" &&\\n            typeof getList === \\"function\\" &&\\n            typeof BILL !== \\"undefined\\";\\n\\n        if (\\n            frappeReady &&\\n            billingReady\\n        ) {\\n\\n            var started =\\n                loadDynamicPricingRules();\\n\\n            if(started===true){\\n                clearInterval(timer);\\n                return;\\n            }\\n        }\\n\\n        if (attempts >= 120) {\\n\\n            clearInterval(timer);\\n\\n            console.warn(\\n                \\"[LIFE Billing] Dynamic Pricing Rule loader timed out waiting for Frappe. Existing bootstrap offers remain active.\\"\\n            );\\n        }\\n\\n    }, 250);\\n})();\\n<\\\\/script>\\n\\n\\n<!-- LIFE-BILLING-FIVE-CORRECTIONS-V1-START -->\\n\\n<style id=\\"life-billing-five-corrections-v1-style\\">\\n/* 1) Right summary: long package names must never push Grand Total out of view. */\\n.sum-sticky{\\n  top:74px !important;\\n  transform:none !important;\\n  max-height:calc(100vh - 88px) !important;\\n  overflow-y:auto !important;\\n  padding-bottom:10px !important;\\n}\\n#bl-brk .brk-row{\\n  align-items:flex-start !important;\\n  gap:12px !important;\\n  min-height:42px;\\n}\\n#bl-brk .brk-row > span:first-child{\\n  flex:1 1 auto;\\n  min-width:0;\\n  white-space:normal !important;\\n  overflow-wrap:anywhere;\\n  word-break:break-word;\\n  line-height:1.4;\\n}\\n#bl-brk .brk-row > b{\\n  flex:0 0 auto;\\n  white-space:nowrap;\\n  text-align:right;\\n}\\n#bl-brk .brk-total{\\n  position:sticky;\\n  bottom:0;\\n  z-index:2;\\n}\\n\\n/* 2) Complimentary dropdown selection. */\\n#bl-comp-sec,\\n#bl-comp-body,\\n#bl-comp-lines,\\n#bl-comp-lines .split-line{\\n  overflow:visible !important;\\n}\\n#bl-comp-lines .split-line{\\n  position:relative;\\n}\\n#bl-comp-lines .comp-dd{\\n  z-index:5000 !important;\\n  max-height:280px !important;\\n}\\n\\n/* 4) Working compact search after a client is opened. */\\n#mini-search{\\n  position:relative;\\n  z-index:280;\\n}\\n#mini-q-dd{\\n  position:absolute;\\n  top:calc(100% + 7px);\\n  left:145px;\\n  right:0;\\n  z-index:6000;\\n}\\n@media(max-width:640px){\\n  #mini-q-dd{left:0;}\\n}\\n</style>\\n\\n<script id=\\"life-billing-five-corrections-v1-script\\">\\n(function(){\\n  \\"use strict\\";\\n\\n  if(window.__lifeBillingFiveCorrectionsV1) return;\\n  window.__lifeBillingFiveCorrectionsV1=true;\\n\\n  function el(id){\\n    return document.getElementById(id);\\n  }\\n\\n  function clean(v){\\n    return String(v==null?\\"\\":v).trim();\\n  }\\n\\n  /* ============================================================\\n     1. SUMMARY CARD\\n     CSS above intentionally allows the summary to grow naturally\\n     while remaining scrollable inside the viewport.\\n     ============================================================ */\\n\\n\\n  /* ============================================================\\n     2. COMPLIMENTARY SESSION PICKER\\n     Use mousedown capture so selection happens before input blur.\\n     ============================================================ */\\n\\n  function lifePickComplimentary(option){\\n    if(!option) return;\\n\\n    var row=option.closest(\\".split-line\\");\\n    if(!row) return;\\n\\n    var codeInput=row.querySelector(\\".comp-code\\");\\n    var qtyInput=row.querySelector(\\".comp-qty\\");\\n    var info=row.querySelector(\\".comp-info\\");\\n    var dropdown=row.querySelector(\\".comp-dd\\");\\n\\n    var code=clean(option.getAttribute(\\"data-c\\"));\\n    if(!code) return;\\n\\n    var picked=null;\\n    (window.COMP_ITEMS||COMP_ITEMS||[]).forEach(function(item){\\n      if(clean(item.item_code)===code){\\n        picked=item;\\n      }\\n    });\\n\\n    if(!picked) return;\\n\\n    var index=parseInt(row.getAttribute(\\"data-i\\")||row.dataset.i||\\"-1\\",10);\\n    if(!(index>=0)) return;\\n\\n    var qty=Math.max(1,parseInt((qtyInput&&qtyInput.value)||1,10)||1);\\n    var maxQty=parseInt(picked.max_qty||0,10)||0;\\n\\n    if(maxQty>0 && qty>maxQty){\\n      qty=maxQty;\\n      if(qtyInput) qtyInput.value=qty;\\n    }\\n\\n    if(codeInput){\\n      codeInput.value=picked.item_name||picked.item_code||code;\\n      codeInput.setAttribute(\\"data-picked-code\\", picked.item_code||code);\\n    }\\n\\n    BILL.comps=BILL.comps||[];\\n    BILL.comps[index]={\\n      item_code:picked.item_code||code,\\n      item_name:picked.item_name||picked.item_code||code,\\n      qty:qty,\\n      comp_price:parseFloat(picked.rate||0)||0,\\n      max_qty_allowed:maxQty\\n    };\\n\\n    if(info){\\n      info.innerHTML=\\n        fmtM(parseFloat(picked.rate||0)||0)+\\n        (maxQty?(\\" · max \\"+maxQty+\\"/bill\\"):\\"\\");\\n    }\\n\\n    if(dropdown){\\n      dropdown.classList.remove(\\"show\\");\\n    }\\n\\n    try{ updateCompSlab(); }catch(e){}\\n  }\\n\\n  document.addEventListener(\\"mousedown\\",function(event){\\n    var option=event.target && event.target.closest\\n      ? event.target.closest(\\"#bl-comp-lines .comp-dd [data-c]\\")\\n      : null;\\n\\n    if(!option) return;\\n\\n    event.preventDefault();\\n    event.stopPropagation();\\n    if(event.stopImmediatePropagation) event.stopImmediatePropagation();\\n\\n    lifePickComplimentary(option);\\n  },true);\\n\\n\\n  /* ============================================================\\n     3 + 5. DISCOUNT APPROVAL REFRESH — WEBPAGE ONLY\\n\\n     No new Server Script is used in this version.\\n\\n     The existing Billing page already reads Discount Approval Request\\n     rows with frappe.client.get_list. We keep that flow and force a\\n     fresh redraw after approvals / requests so newly-created L2 rows\\n     and Administrator approvals appear as soon as Frappe permissions\\n     allow the logged-in user to read them.\\n\\n     IMPORTANT:\\n     If Frappe permissions hide a sibling approval row from the logged-in\\n     user, browser JavaScript cannot bypass that security restriction.\\n     ============================================================ */\\n\\n  function lifeRefreshOpenApprovalInvoice(invoiceName){\\n    invoiceName=clean(invoiceName);\\n    if(!invoiceName) return;\\n\\n    setTimeout(function(){\\n      try{\\n        if(\\n          typeof BILL_DOC!==\\"undefined\\" &&\\n          BILL_DOC &&\\n          BILL_DOC.name===invoiceName &&\\n          typeof refreshOpenBill===\\"function\\"\\n        ){\\n          refreshOpenBill();\\n          return;\\n        }\\n\\n        if(typeof openBill===\\"function\\"){\\n          openBill(invoiceName);\\n        }\\n      }catch(error){\\n        console.warn(\\n          \\"[LIFE Billing] approval refresh failed\\",\\n          error\\n        );\\n      }\\n    },350);\\n  }\\n\\n  /*\\n   * requestNextApproval() / multi-request flow already calls openBill(inv)\\n   * after creation. This MutationObserver additionally refreshes the open\\n   * invoice when the approval drawer is re-rendered, preventing stale rows.\\n   */\\n  var lifeApprovalRefreshTimer=null;\\n\\n  function lifeScheduleApprovalRefresh(){\\n    clearTimeout(lifeApprovalRefreshTimer);\\n\\n    lifeApprovalRefreshTimer=setTimeout(function(){\\n      try{\\n        var invoiceName=\\n          typeof BILL_DOC!==\\"undefined\\" &&\\n          BILL_DOC &&\\n          BILL_DOC.name\\n            ? BILL_DOC.name\\n            : \\"\\";\\n\\n        if(invoiceName){\\n          lifeRefreshOpenApprovalInvoice(\\n            invoiceName\\n          );\\n        }\\n      }catch(error){}\\n    },500);\\n  }\\n\\n  /* ============================================================\\n     4. COMPACT SEARCH\\n     The old mini input called doSearch(), but doSearch renders into\\n     #q-dd inside the hidden hero. This renders a dedicated dropdown.\\n     ============================================================ */\\n\\n  var miniTimer=null;\\n\\n  function ensureMiniDropdown(){\\n    var holder=el(\\"mini-search\\");\\n    if(!holder) return null;\\n\\n    var dd=el(\\"mini-q-dd\\");\\n    if(!dd){\\n      dd=document.createElement(\\"div\\");\\n      dd.id=\\"mini-q-dd\\";\\n      dd.className=\\"search-dd\\";\\n      holder.appendChild(dd);\\n    }\\n    return dd;\\n  }\\n\\n  function miniClose(){\\n    var dd=el(\\"mini-q-dd\\");\\n    if(dd) dd.classList.remove(\\"show\\");\\n  }\\n\\n  function miniPickClient(pid){\\n    var input=el(\\"mini-q\\");\\n    if(input) input.value=\\"\\";\\n    miniClose();\\n    if(typeof openSummary===\\"function\\"){\\n      openSummary(pid);\\n    }\\n  }\\n\\n  function miniRender(raw){\\n    var dd=ensureMiniDropdown();\\n    if(!dd) return;\\n\\n    raw=clean(raw);\\n\\n    if(raw.length<3){\\n      dd.classList.remove(\\"show\\");\\n      dd.innerHTML=\\"\\";\\n      return;\\n    }\\n\\n    var looksNumeric=/^[\\\\\\\\d\\\\\\\\s\\\\\\\\-+()]+$/.test(raw);\\n    var filters;\\n\\n    if(looksNumeric){\\n      var digits=raw.replace(/\\\\\\\\D/g,\\"\\");\\n\\n      if(digits.length===12 && digits.slice(0,2)===\\"91\\"){\\n        digits=digits.slice(2);\\n      }else if(digits.length===11 && digits.charAt(0)===\\"0\\"){\\n        digits=digits.slice(1);\\n      }\\n\\n      if(digits.length>10){\\n        dd.innerHTML=\'<div class=\\"sd-empty\\">📱 A mobile number cannot be more than 10 digits</div>\';\\n        dd.classList.add(\\"show\\");\\n        return;\\n      }\\n\\n      filters=[[\\"mobile\\",\\"like\\",\\"%\\"+digits+\\"%\\"]];\\n    }else{\\n      filters=[[\\"patient_name\\",\\"like\\",\\"%\\"+raw+\\"%\\"]];\\n    }\\n\\n    dd.innerHTML=\'<div class=\\"sd-empty\\">Searching…</div>\';\\n    dd.classList.add(\\"show\\");\\n\\n    getListSilent(\\n      \\"Patient\\",\\n      filters,\\n      [\\n        \\"name\\",\\n        \\"patient_name\\",\\n        \\"mobile\\",\\n        \\"sex\\",\\n        \\"custom_branch\\",\\n        \\"custom_lead\\",\\n        \\"status\\"\\n      ],\\n      {\\n        limit:10,\\n        order_by:\\"modified desc\\"\\n      }\\n    ).then(function(list){\\n      list=list||[];\\n\\n      if(!list.length){\\n        dd.innerHTML=\\n          \'<div class=\\"sd-empty\\">😕 No client found for \\"\'+\\n          esc(raw)+\\n          \'\\"</div>\';\\n        dd.classList.add(\\"show\\");\\n        return;\\n      }\\n\\n      dd.innerHTML=list.map(function(p){\\n        return (\\n          \'<div class=\\"sd-item\\" data-mini-pid=\\"\'+esc(p.name)+\'\\">\'+\\n            \'<div class=\\"sd-av\\" style=\\"background:\'+avc(p.patient_name||p.name)+\'\\">\'+\\n              ini(p.patient_name||p.name)+\\n            \'</div>\'+\\n            \'<div>\'+\\n              \'<div class=\\"sd-name\\">\'+esc(p.patient_name||p.name)+\'</div>\'+\\n              \'<div class=\\"sd-meta\\">\'+\\n                esc(p.name)+\\n                \' · 📱 \'+esc(p.mobile||\\"—\\")+\\n                \' · 📍 \'+esc(p.custom_branch||\\"—\\")+\\n              \'</div>\'+\\n            \'</div>\'+\\n          \'</div>\'\\n        );\\n      }).join(\\"\\");\\n\\n      dd.querySelectorAll(\\"[data-mini-pid]\\").forEach(function(node){\\n        node.addEventListener(\\"mousedown\\",function(event){\\n          event.preventDefault();\\n          miniPickClient(node.getAttribute(\\"data-mini-pid\\"));\\n        });\\n      });\\n\\n      dd.classList.add(\\"show\\");\\n    }).catch(function(error){\\n      dd.innerHTML=\'<div class=\\"sd-empty\\" style=\\"color:var(--red)\\">Search failed. Please try again.</div>\';\\n      dd.classList.add(\\"show\\");\\n      console.warn(\\"[LIFE Billing] compact search failed\\",error);\\n    });\\n  }\\n\\n  function bindMiniSearch(){\\n    var input=el(\\"mini-q\\");\\n    if(!input || input.getAttribute(\\"data-life-mini-fixed\\")===\\"1\\"){\\n      return;\\n    }\\n\\n    input.setAttribute(\\"data-life-mini-fixed\\",\\"1\\");\\n    input.removeAttribute(\\"oninput\\");\\n\\n    input.addEventListener(\\"input\\",function(){\\n      clearTimeout(miniTimer);\\n      var value=this.value;\\n      miniTimer=setTimeout(function(){\\n        miniRender(value);\\n      },220);\\n    });\\n\\n    input.addEvent